//! Independent JavaScript traces generated by harness/economy-state-fixture.mjs.
use serde_json::Value;
use ww2_core::{economy::Mode, economy_state::*};
fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/economy-state.json")).unwrap()
}
fn n(v: &Value) -> f64 {
    v.as_f64().unwrap()
}
fn b(v: &Value) -> bool {
    v.as_bool().unwrap_or(false)
}
fn a(v: &Value) -> &[Value] {
    v.as_array().unwrap()
}
fn slot(v: &Value) -> Option<usize> {
    v.as_u64().map(|n| n as usize)
}
fn army(v: &Value) -> ArmySize {
    match v.as_str().unwrap() {
        "standard" => ArmySize::Standard,
        "large" => ArmySize::Large,
        "massive" => ArmySize::Massive,
        "endless" => ArmySize::Endless,
        _ => panic!(),
    }
}
fn players(v: &Value) -> Vec<PlayerEconomy> {
    a(v).iter()
        .map(|p| PlayerEconomy {
            team: p["team"].as_i64().unwrap() as i32,
            away: b(&p["away"]),
            out: b(&p["out"]),
            mp: n(&p["mp"]),
            mun: n(&p["mun"]),
            fuel: n(&p["fuel"]),
            vp: n(&p["vp"]),
            inc: n(&p["inc"]),
            ..Default::default()
        })
        .collect()
}
fn context(input: &Value, mode: &Value, size: ArmySize, f: impl FnOnce(&Context<'_>)) {
    let queue: Vec<Vec<&str>> = a(&input["units"])
        .iter()
        .map(|u| a(&u["queue"]).iter().map(|s| s.as_str().unwrap()).collect())
        .collect();
    let units: Vec<_> = a(&input["units"])
        .iter()
        .zip(&queue)
        .map(|(u, q)| Unit {
            id: u["id"].as_u64().unwrap(),
            owner: slot(&u["owner"]),
            kind: u["type"].as_str().unwrap(),
            hp: n(&u["hp"]),
            built: n(&u["built"]),
            queue: q,
        })
        .collect();
    let drops: Vec<_> = a(&input["strikes"])
        .iter()
        .map(|d| PendingDrop {
            owner: slot(&d["owner"]).unwrap(),
            kind: d["kind"].as_str().unwrap(),
            live: b(&d["live"]),
        })
        .collect();
    let points: Vec<_> = a(&input["points"])
        .iter()
        .map(|p| Point {
            owner: slot(&p["owner"]),
            cut: b(&p["cut"]),
            mp: n(&p["mp"]),
            vp: n(&p["vp"]),
        })
        .collect();
    let nodes: Vec<_> = a(&input["nodes"])
        .iter()
        .map(|p| Node {
            depot: p["depot"].as_u64(),
            rate: n(&p["rate"]),
            fuel: b(&p["fuel"]),
            region: slot(&p["region"]),
        })
        .collect();
    let regions: Vec<_> = a(&input["regions"])
        .iter()
        .map(|p| Region {
            team: p["team"].as_i64().unwrap() as i32,
            kind: match p["kind"].as_str().unwrap() {
                "city" => RegionKind::City,
                "industrial" => RegionKind::Industrial,
                "resource" => RegionKind::Resource,
                _ => RegionKind::Other,
            },
        })
        .collect();
    f(&Context {
        mode: ModeContext {
            kind: Mode::from_kind(mode["kind"].as_str()),
            defender_team: mode["defenderTeam"].as_i64().map(|n| n as i32),
            income_excluded_slot: slot(&mode["slot"]),
        },
        army: size,
        units: &units,
        drops: &drops,
        points: &points,
        nodes: &nodes,
        world: Some(WorldContext { regions: &regions }),
    });
}
fn set(input: &mut Value, path: &Value) {
    let path = a(path);
    let mut at = input;
    for key in &path[..path.len() - 2] {
        at = if let Some(s) = key.as_str() {
            &mut at[s]
        } else {
            &mut at[key.as_u64().unwrap() as usize]
        };
    }
    let key = &path[path.len() - 2];
    let at = if let Some(s) = key.as_str() {
        &mut at[s]
    } else {
        &mut at[key.as_u64().unwrap() as usize]
    };
    *at = path.last().unwrap().clone();
}
fn bits(actual: f64, expected: &Value, label: &str) {
    assert_eq!(
        format!("{:016x}", actual.to_bits()),
        expected.as_str().unwrap(),
        "{label}"
    );
}

#[test]
fn income_and_population_match_original_javascript_traces() {
    let f = fixture();
    assert_eq!(a(&f["scenarios"]).len(), 37);
    for scenario in a(&f["scenarios"]) {
        let mut input = scenario.get("base").unwrap_or(&f["base"]).clone();
        let mut state = EconomyState {
            players: players(&input["players"]),
        };
        for (tick, step) in a(&scenario["trace"]).iter().enumerate() {
            for path in a(&step["set"]) {
                set(&mut input, path);
            }
            for (p, meta) in state.players.iter_mut().zip(a(&input["players"])) {
                p.away = b(&meta["away"]);
                p.out = b(&meta["out"]);
                p.team = meta["team"].as_i64().unwrap() as i32;
            }
            context(&input, &scenario["mode"], army(&scenario["army"]), |c| {
                state
                    .advance_income(c, n(&step["dt"]), b(&step["winner"]))
                    .unwrap();
                for (slot, expected) in a(&step["expected"]).iter().enumerate() {
                    let p = &state.players[slot];
                    let label = format!(
                        "mode={} army={} tick={tick} slot={slot}",
                        scenario["mode"], scenario["army"]
                    );
                    for (actual, expected) in [
                        Some(p.mp),
                        Some(p.mun),
                        Some(p.fuel),
                        Some(p.vp),
                        Some(p.inc),
                        p.fuel_inc,
                        p.upkeep,
                    ]
                    .iter()
                    .zip(a(&expected["wallet"]))
                    {
                        if let Some(actual) = actual {
                            bits(*actual, expected, &label);
                        } else {
                            assert!(expected.is_null(), "{label}");
                        }
                    }
                    bits(
                        state.population(c, slot).unwrap(),
                        &expected["population"],
                        &label,
                    );
                    bits(
                        state.population_cap(c, slot).unwrap(),
                        &expected["cap"],
                        &label,
                    );
                }
            });
        }
    }
}

#[test]
fn world_caps_split_active_seats_and_preview_is_unscaled() {
    let f = fixture();
    for case in a(&f["capCases"]) {
        let state = EconomyState {
            players: a(&case["teams"])
                .iter()
                .enumerate()
                .map(|(i, t)| PlayerEconomy {
                    team: t.as_i64().unwrap() as i32,
                    out: b(&case["out"][i]),
                    away: b(&case["away"][i]),
                    ..Default::default()
                })
                .collect(),
        };
        let regions = vec![
            Region {
                team: 0,
                kind: RegionKind::Other
            };
            case["owned"].as_u64().unwrap() as usize
        ];
        let c = Context {
            mode: ModeContext {
                kind: Mode::World,
                ..Default::default()
            },
            army: army(&case["army"]),
            units: &[],
            drops: &[],
            points: &[],
            nodes: &[],
            world: Some(WorldContext { regions: &regions }),
        };
        bits(
            state
                .population_cap(&c, slot(&case["slot"]).unwrap())
                .unwrap(),
            &case["expected"],
            "world cap",
        );
    }
    for row in a(&f["preview"]) {
        bits(
            world_cap_preview(n(&row["cap"])).unwrap(),
            &row["expected"],
            "preview",
        );
    }
    assert!(world_cap_preview(f64::INFINITY).is_err());
}

#[test]
fn invalid_context_and_time_leave_wallets_unchanged() {
    let f = fixture();
    let input = &f["base"];
    let mut state = EconomyState {
        players: players(&input["players"]),
    };
    let initial = state.clone();
    context(
        input,
        &serde_json::json!({"kind":"world"}),
        ArmySize::Standard,
        |c| {
            for dt in [-1.0, f64::NAN, f64::INFINITY] {
                assert!(state.advance_income(c, dt, false).is_err());
                assert_eq!(state, initial);
            }
            let missing = Context { world: None, ..*c };
            assert_eq!(
                state.advance_income(&missing, 0.05, false),
                Err(Error::MissingWorld)
            );
            let bad_node = [Node {
                depot: Some(5),
                rate: 1.0,
                fuel: false,
                region: Some(999),
            }];
            let bad = Context {
                nodes: &bad_node,
                ..*c
            };
            assert_eq!(
                state.advance_income(&bad, 0.05, false),
                Err(Error::InvalidRegion(999))
            );
            let bad_drop = [PendingDrop {
                owner: 999,
                kind: "para",
                live: false,
            }];
            let bad = Context {
                drops: &bad_drop,
                ..*c
            };
            assert_eq!(
                state.advance_income(&bad, 0.05, false),
                Err(Error::InvalidSlot(999))
            );
            let bad_unit = [Unit {
                id: 1,
                owner: Some(0),
                kind: "unknown",
                hp: 1.0,
                built: 1.0,
                queue: &[],
            }];
            let bad = Context {
                units: &bad_unit,
                ..*c
            };
            assert!(state.advance_income(&bad, 0.05, false).is_err());
            let duplicate = [c.units[0], c.units[0]];
            let bad = Context {
                units: &duplicate,
                ..*c
            };
            assert_eq!(
                state.advance_income(&bad, 0.05, false),
                Err(Error::DuplicateUnit(1))
            );
            let bad_point = [Point {
                owner: Some(0),
                mp: f64::NAN,
                vp: 0.0,
                cut: false,
            }];
            let bad = Context {
                points: &bad_point,
                ..*c
            };
            assert!(state.advance_income(&bad, 0.05, false).is_err());
            assert!(state.population(c, 999).is_err());
            assert!(state.population_cap(c, 999).is_err());
            assert_eq!(state, initial);
        },
    );
}
